class PaymentService {
  constructor(private converter: CurrencyConverter, private gateway: PaymentGateway) {}

  process(amount, currency) {
    const converted = this.converter.convert(amount, currency);
    const fee = this.calculateFee(converted);
    this.gateway.charge(converted + fee);
  }

  calculateFee(amount) { return amount * 0.02; }
  formatReceipt(tx) { return `Paid ${tx.amount} ${tx.currency}`; }
}

